//! End-to-end tests of the `midi ...` ops through their specs, with fixtures generated by code.

use ferraus_core::prelude::*;
use ferraus_core::testing::{self, TempDir};
use ferraus_core::Runner;
use ferraus_midi::model::{Controller, Program, Tempo, Timed};
use ferraus_midi::{MidiFile, Note, Track};
use std::path::{Path, PathBuf};

fn spec(name: &str) -> OpSpec {
    ferraus_midi::ops().into_iter().find(|o| o.name == name).unwrap()
}

fn run(name: &str, pairs: &[(&str, &str)], inputs: &[&Path], out: Option<&Path>) -> Result<Value> {
    let s = spec(name);
    let a = testing::args(&s, pairs);
    let mut ctx = testing::ctx();
    ctx.command = s.name.to_string();
    ctx.inputs = inputs.iter().map(|p| p.to_path_buf()).collect();
    ctx.globals.output = out.map(|p| p.display().to_string());
    ctx.globals.seed = 7;
    match s.runner {
        Runner::Custom(f) => f(&a, &mut ctx),
        _ => unreachable!(),
    }
}

fn write(dir: &TempDir, name: &str, f: &MidiFile) -> PathBuf {
    let p = dir.path(name);
    std::fs::write(&p, f.to_smf_bytes()).unwrap();
    p
}

fn read(p: &Path) -> MidiFile {
    MidiFile::read(p).unwrap()
}

/// Sixteenth notes with deterministic jitter (±40 ticks at PPQ 480) and a tempo change.
fn jittered() -> MidiFile {
    let mut f = MidiFile::new(480, 120.0);
    f.tempos.push(Timed::new(1920 * 2, Tempo { us_per_quarter: 400_000, track: 0 }));
    let mut x: u64 = 12345;
    for k in 0..64u64 {
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        let j = (x % 81) as i64 - 40;
        let t = (k as i64 * 120 + j).max(0) as u64;
        f.tracks[0].notes.push(Note::new(t, 90, 60 + (k % 12) as u8, 80 + (k % 40) as u8, 0));
    }
    f.fit_ends();
    f
}

#[test]
fn quantize_full_strength_lands_on_grid() {
    let d = TempDir::new("q");
    let inp = write(&d, "take.mid", &jittered());
    let out = d.path("tight.mid");
    let r = run("midi quantize", &[("grid", "1/16"), ("strength", "100%")], &[&inp], Some(&out)).unwrap();
    assert_eq!(r["notes"], 64);
    let f = read(&out);
    assert_eq!(f.note_count(), 64);
    for n in &f.tracks[0].notes {
        assert_eq!(n.tick % 120, 0, "note at {} not on the 1/16 grid", n.tick);
    }
}

#[test]
fn quantize_swing_places_offbeats_at_60_percent() {
    let d = TempDir::new("swing");
    let inp = write(&d, "take.mid", &jittered());
    let out = d.path("swung.mid");
    run("midi quantize", &[("grid", "1/16"), ("swing", "60%")], &[&inp], Some(&out)).unwrap();
    let f = read(&out);
    let mut odd = 0;
    for n in &f.tracks[0].notes {
        let k = n.tick / 120;
        let r = n.tick % 120;
        if k % 2 == 1 {
            assert_eq!(r, 72, "every second sixteenth sits 60% of a grid step late");
            odd += 1;
        } else {
            assert_eq!(r, 0);
        }
    }
    assert!(odd > 20);
}

#[test]
fn quantize_auto_grid_humanize_and_triplets() {
    let d = TempDir::new("qa");
    // eighth-note triplets with jitter
    let mut f = MidiFile::new(480, 100.0);
    for k in 0..24u64 {
        f.tracks[0].notes.push(Note::new(k * 160 + (k % 3) * 5, 60, 64, 100, 0));
    }
    f.fit_ends();
    let inp = write(&d, "trip.mid", &f);
    let out = d.path("auto.mid");
    let r = run("midi quantize", &[("grid", "auto")], &[&inp], Some(&out)).unwrap();
    assert_eq!(r["grid"], "1/8T");
    assert!(read(&out).tracks[0].notes.iter().all(|n| n.tick % 160 == 0));
    // humanize is seeded: same seed, same output
    let h1 = d.path("h1.mid");
    let h2 = d.path("h2.mid");
    run("midi quantize", &[("grid", "1/8T"), ("humanize", "10ms")], &[&inp], Some(&h1)).unwrap();
    run("midi quantize", &[("grid", "1/8T"), ("humanize", "10ms")], &[&inp], Some(&h2)).unwrap();
    assert_eq!(std::fs::read(&h1).unwrap(), std::fs::read(&h2).unwrap());
    let hn = read(&h1);
    let off: Vec<i64> = hn.tracks[0].notes.iter().map(|n| (n.tick as i64 + 80) % 160 - 80).collect();
    assert!(off.iter().any(|o| *o != 0), "humanize moved notes");
    // 10 ms at 100 BPM is 8 ticks; 4 sigma = 32
    assert!(off.iter().all(|o| o.abs() <= 40));
}

#[test]
fn groove_extract_and_apply_round_trip() {
    let d = TempDir::new("groove");
    // reference: a "drummer" with a fixed per-position feel
    let feel = [0i64, 18, -6, 24, 0, 12, -10, 30, 4, 20, -4, 26, 0, 16, -8, 28];
    let vel = [110u8, 70, 90, 60, 105, 72, 88, 62, 108, 68, 92, 58, 112, 74, 86, 64];
    let mut reference = MidiFile::new(480, 120.0);
    for bar in 0..4u64 {
        for (s, (o, v)) in feel.iter().zip(vel).enumerate() {
            let t = (bar * 1920 + s as u64 * 120) as i64 + o;
            reference.tracks[0].notes.push(Note::new(t as u64, 60, 42, v, 9));
        }
    }
    reference.fit_ends();
    let rp = write(&d, "ref.mid", &reference);
    let gp = d.path("groove.json");
    run("midi groove extract", &[("grid", "1/16")], &[&rp], Some(&gp)).unwrap();
    let g: ferraus_midi::Groove = serde_json::from_str(&std::fs::read_to_string(&gp).unwrap()).unwrap();
    assert_eq!(g.steps, 16);
    assert!((g.positions[1].offset - 18.0 / 120.0).abs() < 1e-9);
    // a stiff part on the straight grid picks up the reference timing and accents
    let mut stiff = MidiFile::new(480, 120.0);
    for k in 0..32u64 {
        stiff.tracks[0].notes.push(Note::new(k * 120, 60, 38, 85, 9));
    }
    stiff.fit_ends();
    let sp = write(&d, "stiff.mid", &stiff);
    let op = d.path("grooved.mid");
    run("midi quantize", &[("groove", gp.to_str().unwrap())], &[&sp], Some(&op)).unwrap();
    let out = read(&op);
    let mean_v = vel.iter().map(|v| *v as f64).sum::<f64>() / 16.0;
    for (k, n) in out.tracks[0].notes.iter().enumerate() {
        let s = k % 16;
        assert_eq!(n.tick as i64, k as i64 * 120 + feel[s], "timing at step {s}");
        let want = (85.0 + vel[s] as f64 - mean_v).round() as u8;
        assert_eq!(n.velocity, want, "velocity at step {s}");
    }
}

#[test]
fn transpose_skips_drums_and_drops_out_of_range() {
    let d = TempDir::new("tr");
    let f = MidiFile::from_beat_notes(
        &[(60, 0.0, 1.0, 100, 1), (36, 1.0, 1.0, 100, 10), (126, 2.0, 1.0, 100, 1)],
        120.0,
        480,
    );
    let inp = write(&d, "in.mid", &f);
    let out = d.path("up.mid");
    let r = run("midi transpose", &[("semitones", "+3")], &[&inp], Some(&out)).unwrap();
    assert_eq!(r["notes_dropped"], 1);
    let g = read(&out);
    let p: Vec<u8> = g.tracks[0].notes.iter().map(|n| n.pitch).collect();
    assert_eq!(p, vec![63, 36]);
    let out2 = d.path("down.mid");
    run("midi transpose", &[("semitones", "-12st"), ("include-drums", "true")], &[&inp], Some(&out2)).unwrap();
    let p: Vec<u8> = read(&out2).tracks[0].notes.iter().map(|n| n.pitch).collect();
    assert_eq!(p, vec![48, 24, 114]);
}

#[test]
fn velocity_set_scale_compress_range() {
    let d = TempDir::new("vel");
    let f =
        MidiFile::from_beat_notes(&[(60, 0.0, 1.0, 40, 1), (62, 1.0, 1.0, 80, 1), (64, 2.0, 1.0, 120, 1)], 120.0, 480);
    let inp = write(&d, "in.mid", &f);
    let v = |pairs: &[(&str, &str)]| {
        let out = d.path(&format!("v{}.mid", pairs.len() * 100 + pairs.iter().map(|p| p.1.len()).sum::<usize>()));
        let _ = std::fs::remove_file(&out);
        run("midi velocity", pairs, &[&inp], Some(&out)).unwrap();
        read(&out).tracks[0].notes.iter().map(|n| n.velocity).collect::<Vec<u8>>()
    };
    assert_eq!(v(&[("scale", "1.2")]), vec![48, 96, 127]);
    assert_eq!(v(&[("compress", "50%")]), vec![60, 80, 100]);
    assert_eq!(v(&[("set", "90")]), vec![90, 90, 90]);
    assert_eq!(v(&[("range", "60..100")]), vec![60, 80, 100]);
    assert!(run("midi velocity", &[("range", "100..60")], &[&inp], Some(&d.path("bad.mid"))).is_err());
}

#[test]
fn legato_extends_to_next_onset() {
    let d = TempDir::new("leg");
    let f = MidiFile::from_beat_notes(
        &[(60, 0.0, 0.25, 100, 1), (64, 0.0, 0.25, 100, 1), (62, 1.0, 0.25, 100, 1), (65, 3.0, 0.5, 100, 1)],
        120.0,
        480,
    );
    let inp = write(&d, "in.mid", &f);
    let out = d.path("leg.mid");
    run("midi legato", &[], &[&inp], Some(&out)).unwrap();
    let g = read(&out);
    let ends: Vec<(u8, u64)> = g.tracks[0].notes.iter().map(|n| (n.pitch, n.end())).collect();
    assert_eq!(ends, vec![(60, 480), (64, 480), (62, 1440), (65, 1680)]);
    let out2 = d.path("gap.mid");
    run("midi legato", &[("gap", "0.25b")], &[&inp], Some(&out2)).unwrap();
    assert_eq!(read(&out2).tracks[0].notes[0].end(), 360);
}

#[test]
fn tempo_set_and_scale_keep_beats() {
    let d = TempDir::new("tempo");
    let f = MidiFile::from_beat_notes(&[(60, 4.0, 1.0, 100, 1)], 100.0, 480);
    let inp = write(&d, "in.mid", &f);
    let out = d.path("t.mid");
    let r = run("midi tempo", &[("set", "120")], &[&inp], Some(&out)).unwrap();
    assert_eq!(r["bpm_after"], 120.0);
    let g = read(&out);
    assert_eq!(g.tracks[0].notes[0].tick, 1920);
    assert!((g.notes_seconds()[0].start_s - 2.0).abs() < 1e-9);
    let out2 = d.path("t2.mid");
    run("midi tempo", &[("scale", "2")], &[&inp], Some(&out2)).unwrap();
    assert!((read(&out2).notes_seconds()[0].start_s - 1.2).abs() < 1e-6);
    assert!(run("midi tempo", &[], &[&inp], Some(&d.path("x.mid"))).is_err());
}

fn song() -> MidiFile {
    let mut f = MidiFile::new(480, 120.0);
    f.time_signatures.push(Timed::new(
        0,
        ferraus_midi::model::TimeSig { numerator: 4, denominator: 4, clocks_per_click: 24, notated_32nds: 8, track: 0 },
    ));
    let mut a = Track::new();
    a.set_name("Keys");
    a.programs.push(Timed::new(0, Program { channel: 0, program: 0 }));
    a.controllers.push(Timed::new(0, Controller { channel: 0, controller: 7, value: 90 }));
    a.controllers.push(Timed::new(2000, Controller { channel: 0, controller: 7, value: 70 }));
    for k in 0..16u64 {
        a.notes.push(Note::new(k * 480, 400, 60 + (k % 5) as u8, 100, 0));
    }
    let mut b = Track::new();
    b.set_name("Bass");
    b.programs.push(Timed::new(0, Program { channel: 1, program: 33 }));
    for k in 0..8u64 {
        b.notes.push(Note::new(k * 960, 900, 36, 100, 1));
    }
    f.tracks = vec![Track::new(), a, b];
    f.fit_ends();
    f
}

#[test]
fn split_merge_round_trip() {
    let d = TempDir::new("split");
    let inp = write(&d, "song.mid", &song());
    let r = run("midi split-tracks", &[], &[&inp], Some(&d.path("song.mid.out.mid"))).unwrap();
    let parts = r["parts"].as_array().unwrap();
    assert_eq!(parts.len(), 2);
    assert_eq!(parts[0]["role"], "track2");
    let p1 = PathBuf::from(parts[0]["output"].as_str().unwrap());
    let p2 = PathBuf::from(parts[1]["output"].as_str().unwrap());
    assert!(p1.to_string_lossy().ends_with(".track2.mid"));
    let a = read(&p1);
    assert_eq!(a.note_count(), 16);
    assert_eq!(a.tracks[0].name().as_deref(), Some("Keys"));
    assert_eq!(a.time_signatures.len(), 1);
    // merge them back
    let out = d.path("merged.mid");
    let r = run("midi merge", &[], &[&p1, &p2], Some(&out)).unwrap();
    assert_eq!(r["notes"], 24);
    let m = read(&out);
    assert_eq!(m.tracks.len(), 2);
    assert_eq!(m.notes_seconds(), {
        let mut s = song().notes_seconds();
        for n in &mut s {
            n.track -= 1;
        }
        s
    });
    // by channel
    let r = run("midi split-tracks", &[("by", "channel")], &[&inp], Some(&d.path("ch.mid"))).unwrap();
    let roles: Vec<&str> = r["parts"].as_array().unwrap().iter().map(|p| p["role"].as_str().unwrap()).collect();
    assert_eq!(roles, vec!["ch1", "ch2"]);
    // single-track merge
    let out = d.path("single.mid");
    run("midi merge", &[("mode", "single")], &[&p1, &p2], Some(&out)).unwrap();
    let s = read(&out);
    assert_eq!(s.tracks.len(), 1);
    assert_eq!(s.note_count(), 24);
}

#[test]
fn trim_by_beats_and_seconds() {
    let d = TempDir::new("trim");
    let inp = write(&d, "song.mid", &song());
    let out = d.path("t.mid");
    run("midi trim", &[("range", "4b..8b")], &[&inp], Some(&out)).unwrap();
    let t = read(&out);
    // keys: notes at beats 4..7 → 4 notes; bass: note at beat 4 (tick 1920) and beat 6
    assert_eq!(t.tracks[1].notes.len(), 4);
    assert_eq!(t.tracks[1].notes[0].tick, 0);
    assert_eq!(t.tracks[2].notes.len(), 2);
    assert!(t.duration_ticks() <= 1920);
    // the volume in effect at the start (90 then 70 at tick 2000) is carried
    let cc: Vec<(u64, u8)> = t.tracks[1].controllers.iter().map(|c| (c.tick, c.data.value)).collect();
    assert_eq!(cc, vec![(0, 90), (80, 70)]);
    assert_eq!(t.tracks[1].programs.len(), 1);
    // seconds: 120 BPM, 1 s = 2 beats; notes crossing the start are clipped
    let out2 = d.path("s.mid");
    run("midi trim", &[("range", "2.1s..3s")], &[&inp], Some(&out2)).unwrap();
    let s = read(&out2);
    let first = &s.tracks[2].notes[0];
    assert_eq!(first.tick, 0);
    assert_eq!(first.duration, 1920 + 900 - 2016);
    assert!(run("midi trim", &[("range", "8b..4b")], &[&inp], Some(&d.path("bad.mid"))).is_err());
}

#[test]
fn info_to_json_from_json_ops() {
    let d = TempDir::new("info");
    let inp = write(&d, "song.mid", &song());
    let info = run("midi info", &[], &[&inp], None).unwrap();
    assert_eq!(info["notes"], 24);
    assert_eq!(info["tracks"][1]["name"], "Keys");
    assert_eq!(info["tracks"][2]["programs"][0]["name"], "Electric Bass (finger)");
    assert_eq!(info["duration"]["seconds"], read(&inp).duration_seconds());
    let js = d.path("song.json");
    run("midi to-json", &[], &[&inp], Some(&js)).unwrap();
    let v: Value = serde_json::from_str(&std::fs::read_to_string(&js).unwrap()).unwrap();
    assert_eq!(v["tracks"][1]["notes"][0]["name"], "C4");
    assert_eq!(v["tracks"][1]["notes"][0]["duration_s"], 400.0 / 960.0);
    let back = d.path("back.mid");
    run("midi from-json", &[], &[&js], Some(&back)).unwrap();
    assert_eq!(std::fs::read(&back).unwrap(), std::fs::read(&inp).unwrap());
    let hi = d.path("hi.mid");
    run("midi from-json", &[("ppq", "960")], &[&js], Some(&hi)).unwrap();
    let h = read(&hi);
    assert_eq!(h.ppq(), Some(960));
    assert_eq!(h.notes_seconds(), read(&inp).notes_seconds());
    // ops also read JSON input directly and can write JSON
    let q = d.path("q.json");
    run("midi quantize", &[], &[&js], Some(&q)).unwrap();
    assert!(MidiFile::read(&q).is_ok());
    // a missing input is an input error
    let e = run("midi info", &[], &[&d.path("nope.mid")], None).unwrap_err();
    assert_eq!(e.kind, ErrorKind::InputMissing);
}

#[test]
fn every_op_has_docs_and_examples() {
    for o in ferraus_midi::ops() {
        assert!(!o.about.is_empty(), "{} needs about", o.name);
        assert!(o.examples.len() >= 2, "{} needs two examples", o.name);
        for p in &o.params {
            assert!(!p.help.is_empty(), "{} --{} needs help", o.name, p.name);
        }
    }
}
